const input = $('Normalize Run Input').first().json;
const players = [
  { seleccion: 'Ecuador', jugador: 'Moisés Caicedo' },
  { seleccion: 'Ecuador', jugador: 'Piero Hincapié' },
  { seleccion: 'Ecuador', jugador: 'Willian Pacho' },
  { seleccion: 'Ecuador', jugador: 'Gonzalo Plata' },
  { seleccion: 'Ecuador', jugador: 'Kendry Páez' },
  { seleccion: 'Ecuador', jugador: 'Enner Valencia' },
  { seleccion: 'Colombia', jugador: 'James Rodríguez' },
  { seleccion: 'Colombia', jugador: 'Luis Díaz' },
  { seleccion: 'Colombia', jugador: 'Juan Fernando Quintero' },
  { seleccion: 'Colombia', jugador: 'Jhon Arias' },
  { seleccion: 'Argentina', jugador: 'Lionel Messi' },
  { seleccion: 'Argentina', jugador: 'Julián Álvarez' },
  { seleccion: 'Argentina', jugador: 'Emiliano Martínez' },
  { seleccion: 'Uruguay', jugador: 'Federico Valverde' },
  { seleccion: 'Paraguay', jugador: 'Julio Enciso' },
  { seleccion: 'Paraguay', jugador: 'Miguel Almirón' },
];

return players.map((player) => {
  const query = `\"${player.jugador}\" when:${input.google_when || '1d'}`;
  const feedUrl = `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=es-419&gl=EC&ceid=EC:es-419`;
  return {
    json: {
      ...player,
      run_id: input.run_id || '',
      requested_window: input.requested_window || '24h',
      window_ms: input.window_ms || 24 * 60 * 60 * 1000,
      source_kind: 'google_news_rss',
      source_name: 'Google News RSS',
      feed_url: feedUrl,
    },
  };
});

const input = $('Normalize Run Input').first().json;
const now = Date.now();
const maxAgeMs = Number(input.window_ms) || 24 * 60 * 60 * 1000;
const seen = new Set();
const output = [];

for (const item of items) {
  const row = item.json;
  const title = (row.titular || '').trim();
  const link = (row.link || '').trim();
  const source = (row.fuente || '').trim();
  const published = Date.parse(row.fecha_publicacion || '');
  const isRecent = Number.isNaN(published) ? true : now - published <= maxAgeMs;
  const dedupeKey = row.jugador + '::' + (link || (title + '::' + source));

  if (!title || !link || !isRecent || seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  output.push(item);
}

return output;

const footballKeywords = [
  'gol','goles','asistencia','asistencias','anoto','anotó','marco','marcó','convirtio','convirtió',
  'partido','partidos','entrenador','tecnico','técnico','dt','club','seleccion','selección','convocado','convocatoria',
  'alineacion','alineación','titular','suplente','capitan','capitán','vestuario','lesion','lesión','lesionado','recuperacion','recuperación',
  'fichaje','transferencia','mercado','renovacion','renovación','contrato','debut','victoria','derrota','empate','torneo','liga','copa',
  'champions','libertadores','sudamericana','eliminatorias','mundial','chelsea','liverpool','leverkusen','psg','barcelona','real madrid',
  'arsenal','brighton','premier league','bundesliga','ligue 1','serie a','la liga'
];

function normalize(text) {
  return (text || '')
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

return items.map((item) => {
  const row = item.json;
  const combined = normalize([row.jugador, row.titular, row.fuente, row.snippet].join(' '));
  const player = normalize(row.jugador || '');
  const hasPlayer = player && combined.includes(player);
  const matchedSignals = footballKeywords.filter((keyword) => combined.includes(normalize(keyword)));
  const passDirect = hasPlayer && matchedSignals.length > 0;

  return {
    json: {
      ...row,
      pass_direct: passDirect,
      football_signals: matchedSignals.slice(0, 6).join(' || '),
    },
  };
});

return items.filter((item) => item.json.pass_direct === true).map((item) => ({
  json: {
    ...item.json,
    classification_source: 'heuristic',
  },
}));

const batchSize = 10;
const fallbackModels = [
  'gemma-3-27b-it',
  'gemini-3.1-flash-lite-preview',
];

const ambiguousItems = items.filter((item) => item.json.pass_direct !== true);
const itemsWithIds = ambiguousItems.map((item, index) => ({ ...item.json, __sourceIndex: index }));
const output = [];
for (let i = 0; i < itemsWithIds.length; i += batchSize) {
  const rows = itemsWithIds.slice(i, i + batchSize);
  const compactRows = rows.map((row) => ({
    id_noticia: row.id_noticia,
    jugador: row.jugador,
    titular: row.titular,
    fuente: row.fuente,
    snippet: (row.snippet || '').toString().slice(0, 280),
  }));

  const aiPrompt = `Clasifica noticias y responde SOLO con JSON valido.\n\nObjetivo: determinar si cada noticia pertenece claramente al ambito del futbol profesional o de selecciones.\n\nRegla de decision:\n- true: si la noticia trata sobre futbol, futbolistas, clubes, selecciones, entrenadores, partidos, torneos, fichajes, lesiones deportivas, convocatorias o rendimiento futbolistico.\n- false: si la noticia NO deja claro el contexto futbolistico.\n\nNo evalues si la noticia es buena o mala. Solo si es de futbol o no.\n\nDevuelve este formato exacto:\n{\n  \"results\": [\n    {\"id_noticia\": \"...\", \"es_futbol\": true, \"razon\": \"breve\"}\n  ]\n}\n\nNoticias a clasificar:\n${JSON.stringify(compactRows, null, 2)}`;

  fallbackModels.forEach((model, attemptOrder) => {
    output.push({
      json: {
        batch_id: `gemini-football-batch-${(i / batchSize) + 1}`,
        batch_news: rows,
        ai_prompt: aiPrompt,
        model,
        attempt_order: attemptOrder,
      },
    });
  });
}
return output;

function extractText(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = extractText(item);
      if (found) return found;
    }
  }
  if (value && typeof value === 'object') {
    if (Array.isArray(value.candidates)) {
      for (const candidate of value.candidates) {
        const parts = candidate?.content?.parts;
        if (!Array.isArray(parts)) continue;
        const text = parts
          .filter((part) => !part?.thought)
          .map((part) => part?.text || '')
          .join('')
          .trim();
        if (text) return text;
      }
    }
    if (Array.isArray(value.choices) && value.choices[0]?.message?.content) {
      return value.choices[0].message.content;
    }
    const preferredKeys = ['content', 'text', 'output', 'response', 'message'];
    for (const key of preferredKeys) {
      if (key in value) {
        const found = extractText(value[key]);
        if (found) return found;
      }
    }
    for (const nested of Object.values(value)) {
      const found = extractText(nested);
      if (found) return found;
    }
  }
  return '';
}

function parseJsonFromText(text) {
  const cleaned = String(text || '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced) return JSON.parse(fenced[1]);
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) return JSON.parse(cleaned.slice(start, end + 1));
  throw new Error('No se pudo parsear JSON desde la respuesta de Gemini');
}

const sourceBatches = $('Build Gemini Batches').all().map((item) => item.json ?? {});
const attemptsByBatch = new Map();

items.forEach((item, index) => {
  const response = item.json ?? {};
  const source = sourceBatches[index] ?? {};
  const attempt = { ...source, ...response };
  const key = attempt.batch_id || `gemini-batch-${index + 1}`;
  if (!attemptsByBatch.has(key)) attemptsByBatch.set(key, []);
  attemptsByBatch.get(key).push(attempt);
});

const output = [];
for (const [batchId, attempts] of attemptsByBatch.entries()) {
  const ordered = attempts.sort((a, b) => (a.attempt_order ?? 999) - (b.attempt_order ?? 999));
  let chosen = null;
  let parsed = null;
  for (const attempt of ordered) {
    try {
      if (attempt.error) continue;
      const modelText = extractText(attempt);
      if (!modelText) continue;
      const maybeParsed = parseJsonFromText(modelText);
      if (Array.isArray(maybeParsed.results)) {
        chosen = attempt;
        parsed = maybeParsed;
        break;
      }
    } catch {}
  }
  if (!chosen || !parsed) continue;
  const footballIds = new Set(parsed.results
    .filter((row) => row && row.id_noticia && row.es_futbol === true)
    .map((row) => row.id_noticia));
  for (const row of chosen.batch_news || []) {
    if (footballIds.has(row.id_noticia)) {
      const cleanRow = { ...row };
      delete cleanRow.__sourceIndex;
      output.push({ json: { ...cleanRow, classification_source: 'ai' } });
    }
  }
}
return output;

const input = $('Normalize Run Input').first().json;
const runId = String(input.run_id || '').trim();

return [{
  json: {
    action: runId ? 'upsert_news_staging' : 'upsert_news',
    ...(runId ? { run_id: runId } : {}),
    rows: items.map((item) => item.json),
  },
}];

const counters = new Map();

return items.map((item) => {
  const row = item.json ?? {};
  const key = `${row.seleccion || ''}||${row.jugador || ''}`;
  const nextPosition = (counters.get(key) || 0) + 1;
  counters.set(key, nextPosition);

  return {
    json: {
      ...row,
      google_position: nextPosition,
    },
  };
});

function normalizeWindow(value) {
  const raw = String(value ?? '24h').trim().toLowerCase();
  if (['1h', 'hour', 'last_hour', 'ultima_hora', 'última_hora'].includes(raw)) {
    return { requested_window: '1h', google_when: '1h', window_ms: 60 * 60 * 1000 };
  }
  return { requested_window: '24h', google_when: '1d', window_ms: 24 * 60 * 60 * 1000 };
}

const source = items[0]?.json ?? {};
const body = source.body ?? source;
const normalized = normalizeWindow(body.window ?? body.requested_window ?? body.when);
const runId = String(body.run_id ?? body.runId ?? '').trim();

return [{
  json: {
    ...normalized,
    run_id: runId,
    mode: runId ? 'staging' : 'live',
  },
}];

const batch = $('Build Upsert Batch').first().json;
const runId = batch.run_id || null;
const persisted = items[0]?.json ?? {};

return [{
  json: {
    status: 'ok',
    mode: runId ? 'staging' : 'live',
    run_id: runId,
    persisted: persisted.upserted || persisted.staged_news || 0,
    valid: persisted.valid || 0,
    received: persisted.received || 0,
    sample: (batch.rows || []).slice(0, 5).map((row) => ({
      jugador: row.jugador,
      titular: row.titular,
      fuente: row.fuente,
      source: row.classification_source || 'unknown',
    })),
    note: runId
      ? 'Discovery staged safely. Current approval universe remains untouched until promote.'
      : 'Discovery rebuilt the live Supabase universe.',
  },
}];

const source = items[0]?.json ?? {};
const rows = Array.isArray(source.rows) ? source.rows : [];
const batchSize = 100;

const nullable = (value) => {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
};

const nullableNumber = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const parsed = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

const safeTimestamp = (value) => {
  const parsed = Date.parse(value ?? '');
  return Number.isNaN(parsed) ? 0 : parsed;
};

const sortRows = (input) => [...input].sort((left, right) => {
  const byGoogle = (left.google_position ?? Number.POSITIVE_INFINITY) - (right.google_position ?? Number.POSITIVE_INFINITY);
  if (byGoogle !== 0) return byGoogle;
  return safeTimestamp(right.fecha_publicacion) - safeTimestamp(left.fecha_publicacion);
});

const sanitized = rows
  .map((row) => ({
    id_noticia: String(row.id_noticia ?? '').trim(),
    seleccion: nullable(row.seleccion),
    jugador: nullable(row.jugador),
    titular: String(row.titular ?? '').trim(),
    fuente: nullable(row.fuente),
    fecha_publicacion: nullable(row.fecha_publicacion),
    link: nullable(row.link),
    snippet: nullable(row.snippet),
    fuente_origen: nullable(row.fuente_origen),
    cluster_id: nullable(row.cluster_id),
    estado_revision: (nullable(row.estado_revision) ?? 'pendiente').toLowerCase(),
    fecha_detectada: nullable(row.fecha_detectada),
    tema_principal: nullable(row.tema_principal),
    google_position: nullableNumber(row.google_position),
  }))
  .filter((row) => row.id_noticia && row.titular && row.estado_revision === 'pendiente');

const byPlayer = new Map();
for (const row of sanitized) {
  const key = `${row.seleccion ?? ''}||${row.jugador ?? ''}`;
  if (!byPlayer.has(key)) byPlayer.set(key, []);
  byPlayer.get(key).push(row);
}

const createdAt = new Date().toISOString();
const anchorDate = createdAt.slice(0, 10).replace(/-/g, '');
let batchIndex = 1;
const output = [];

for (const [key, playerRows] of byPlayer.entries()) {
  const [seleccion, jugador] = key.split('||');
  const sortedRows = sortRows(playerRows);

  for (let offset = 0; offset < sortedRows.length; offset += batchSize) {
    const batchRows = sortedRows.slice(offset, offset + batchSize);
    const compactRows = batchRows.map((row, rowIndex) => ({
      id: `n${rowIndex + 1}`,
      t: row.titular,
      f: row.fuente,
      d: row.fecha_publicacion,
      p: row.google_position,
      s: (row.snippet || '').toString().slice(0, 220),
    }));
    const idAliases = Object.fromEntries(batchRows.map((row, rowIndex) => [`n${rowIndex + 1}`, row.id_noticia]));

    const prompt = `Agrupa noticias de UN SOLO jugador en storylines editoriales. Une solo notas que compartan el mismo hecho/eje narrativo. Separa temas distintos aunque sean del mismo jugador. No hagas clusters de 1 noticia. Usa SOLO los ids cortos recibidos. Responde JSON estricto, sin markdown.\nFormato requerido: objeto JSON con una propiedad clusters y una propiedad unassigned_ids. Cada cluster debe tener: tema, resumen, ids.\nReglas críticas:\n- tema debe ser un titular editorial específico derivado de las noticias.\n- resumen debe ser una frase factual específica derivada de las noticias.\n- Prohibido devolver placeholders como title, tema breve, headline, common fact, resumen factual o texto de ejemplo.\n- Si dos o más noticias tratan claramente el mismo hecho, DEBEN ir en clusters.\n- Usa unassigned_ids solo para noticias realmente aisladas o ambiguas.\nJugador: ${jugador || 'Sin jugador'}\nSeleccion: ${seleccion || 'Sin seleccion'}\nLote: ${Math.floor(offset / batchSize) + 1}\nNoticias: ${JSON.stringify(compactRows)}`;

    output.push({
      json: {
        batch_index: batchIndex,
        batch_key: `${key}::${Math.floor(offset / batchSize) + 1}`,
        seleccion: seleccion || null,
        jugador: jugador || null,
        created_at: createdAt,
        anchor_date: anchorDate,
        batch_news: batchRows,
        id_aliases: idAliases,
        ai_prompt: prompt,
      },
    });

    batchIndex += 1;
  }
}

return output;

function normalizeText(value) {
  return (value || '')
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function slug(value) {
  return normalizeText(value)
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
}

function stableHash(value) {
  let hash = 5381;
  for (const char of value) {
    hash = ((hash << 5) + hash) ^ char.charCodeAt(0);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function unique(values) {
  return Array.from(new Set(values));
}

function safeTimestamp(value) {
  const parsed = Date.parse(value ?? '');
  return Number.isNaN(parsed) ? 0 : parsed;
}

function sortRows(input) {
  return [...input].sort((left, right) => {
    const byGoogle = (left.google_position ?? Number.POSITIVE_INFINITY) - (right.google_position ?? Number.POSITIVE_INFINITY);
    if (byGoogle !== 0) return byGoogle;
    return safeTimestamp(right.fecha_publicacion) - safeTimestamp(left.fecha_publicacion);
  });
}

function computeAvgGooglePosition(rows) {
  const positions = rows
    .map((row) => row.google_position)
    .filter((value) => typeof value === 'number' && Number.isFinite(value));

  if (!positions.length) return null;
  const total = positions.reduce((sum, value) => sum + value, 0);
  return Number((total / positions.length).toFixed(4));
}

function parseJsonFromUnknown(value) {
  if (!value) return null;
  if (typeof value === 'object') {
    if (Array.isArray(value.clusters) || Array.isArray(value.unassigned_ids)) return value;
    return null;
  }
  if (typeof value !== 'string') return null;

  const cleaned = value.trim();
  if (!cleaned) return null;

  try { return JSON.parse(cleaned); } catch {}
  const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced) {
    try { return JSON.parse(fenced[1]); } catch {}
  }
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    try { return JSON.parse(cleaned.slice(start, end + 1)); } catch {}
  }
  const arrayStart = cleaned.indexOf('[');
  const arrayEnd = cleaned.lastIndexOf(']');
  if (arrayStart !== -1 && arrayEnd !== -1 && arrayEnd > arrayStart) {
    try { return JSON.parse(cleaned.slice(arrayStart, arrayEnd + 1)); } catch {}
  }
  return null;
}

function extractPayload(value) {
  if (!value) return null;
  if (typeof value === 'object') {
    if (Array.isArray(value.clusters) || Array.isArray(value.unassigned_ids)) return value;
    if (Array.isArray(value.candidates)) {
      for (const candidate of value.candidates) {
        const parts = candidate?.content?.parts;
        if (!Array.isArray(parts)) continue;
        for (const part of parts) {
          if (part?.thought) continue;
          const found = extractPayload(part?.text);
          if (found) return found;
        }
      }
    }
    if (Array.isArray(value.choices) && value.choices[0]?.message?.content) {
      return extractPayload(parseJsonFromUnknown(value.choices[0].message.content));
    }
    if (Array.isArray(value) && value.length) {
      for (const entry of value) {
        const found = extractPayload(entry);
        if (found) return found;
      }
    }
    for (const nested of Object.values(value)) {
      const found = extractPayload(nested);
      if (found) return found;
    }
  }
  const parsed = parseJsonFromUnknown(value);
  if (parsed && typeof parsed === 'object' && (Array.isArray(parsed.clusters) || Array.isArray(parsed.unassigned_ids))) {
    return parsed;
  }
  return null;
}

function buildClusterId({ seleccion, jugador, anchorDate, key }) {
  const prefix = [slug(seleccion || 'sin-seleccion') || 'sin-seleccion', slug(jugador || 'sin-jugador') || 'sin-jugador', anchorDate].join('-');
  return `${prefix}-${stableHash(key)}`.slice(0, 120);
}

const requestBatches = $('Build Cluster Requests').all();

return items.map((item, index) => {
  const batch = requestBatches[index]?.json;
  if (!batch) {
    throw new Error(`Missing source batch for AI response index ${index}`);
  }

  const response = item.json ?? {};
  const payload = extractPayload(response) || {};
  const rawClusters = Array.isArray(payload.clusters) ? payload.clusters : [];
  const rawUnassigned = Array.isArray(payload.unassigned_ids) ? payload.unassigned_ids : [];
  const batchNews = Array.isArray(batch.batch_news) ? batch.batch_news : [];
  const newsById = new Map(batchNews.map((row) => [row.id_noticia, row]));
  const aliasToReal = new Map(Object.entries(batch.id_aliases || {}).map(([alias, id]) => [String(alias), String(id)]));
  const usedIds = new Set();
  const acceptedClusters = [];

  for (const [clusterIndex, cluster] of rawClusters.entries()) {
    if (!cluster || typeof cluster !== 'object') continue;
    const rawIds = Array.isArray(cluster.ids)
      ? cluster.ids
      : (Array.isArray(cluster.ids_noticias) ? cluster.ids_noticias : []);
    const candidateIds = rawIds
      .map((id) => {
        const key = String(id || '').trim();
        return aliasToReal.get(key) || key;
      })
      .filter(Boolean);

    const ids = [];
    for (const id of candidateIds) {
      if (!newsById.has(id) || usedIds.has(id)) continue;
      ids.push(id);
      usedIds.add(id);
    }

    if (ids.length < 2) {
      for (const id of ids) usedIds.delete(id);
      continue;
    }

    const rows = sortRows(ids.map((id) => newsById.get(id)).filter(Boolean));
    const sortedIds = rows.map((row) => row.id_noticia).sort();
    const rawTema = String(cluster.tema_principal || cluster.tema || '').trim();
    const normalizedTema = normalizeText(rawTema);
    const placeholderTema = /^(tema breve|title|headline|common fact|tema sin titulo|tema-sin-titulo|titulo editorial especifico basado en el hecho comun|titulo editorial specific based on common fact|title editorial specific based on common fact|specific headline based on the common fact)$/i.test(normalizedTema) || normalizedTema.includes('placeholder') || normalizedTema.includes('specific based on common fact') || normalizedTema.includes('basado en el hecho comun');
    const tema = placeholderTema ? String(rows[0]?.titular || sortedIds[0] || 'tema-sin-titulo').trim() : (rawTema || String(rows[0]?.titular || sortedIds[0] || 'tema-sin-titulo').trim());
    const rawResumen = String(cluster.resumen_cluster || cluster.resumen || '').trim();
    const normalizedResumen = normalizeText(rawResumen);
    const placeholderResumen = /^(1 frase factual|factual sentence|summary|resumen|resumen factual especifico en una frase|resumen factual especifico en una frase)$/i.test(normalizedResumen) || normalizedResumen.includes('placeholder') || normalizedResumen.includes('specific factual');
    const resumen = placeholderResumen ? String(rows[0]?.snippet || rows[0]?.titular || '').trim() || null : (rawResumen || String(rows[0]?.snippet || rows[0]?.titular || '').trim() || null);
    const clusterId = buildClusterId({
      seleccion: batch.seleccion,
      jugador: batch.jugador,
      anchorDate: batch.anchor_date,
      key: `${batch.batch_index}:${clusterIndex + 1}:${sortedIds.join('|')}`,
    });

    acceptedClusters.push({
      cluster_id: clusterId,
      seleccion: batch.seleccion,
      jugador: batch.jugador,
      tema_principal: tema,
      resumen_cluster: resumen,
      tag_editorial: null,
      fecha_creacion_cluster: batch.created_at,
      avg_google_position: computeAvgGooglePosition(rows),
      sources: rows.map((row, sourceOrder) => ({
        id_noticia: row.id_noticia,
        source_order: sourceOrder,
        source_title_snapshot: row.titular || null,
        source_link_snapshot: row.link || null,
        source_name_snapshot: row.fuente || null,
      })),
    });
  }

  if (!acceptedClusters.length && batchNews.length >= 2) {
    const rows = sortRows(batchNews).slice(0, Math.min(3, batchNews.length));
    const sortedIds = rows.map((row) => row.id_noticia).sort();
    acceptedClusters.push({
      cluster_id: buildClusterId({
