const finalClusters = [];
const clusterIds = new Set();
const membershipCounts = new Map();

const registerClusterId = (candidate) => {
  let current = candidate;
  let index = 1;
  while (clusterIds.has(current)) {
    current = `${candidate}-${index}`.slice(0, 120);
    index += 1;
  }
  clusterIds.add(current);
  return current;
};

