  for (const cluster of batch.ai_clusters || []) {
    const clusterId = registerClusterId(cluster.cluster_id);
    finalClusters.push({
      ...cluster,
      cluster_id: clusterId,
    });

    for (const source of cluster.sources || []) {
      membershipCounts.set(source.id_noticia, (membershipCounts.get(source.id_noticia) || 0) + 1);
    }
  }
}

const duplicatedAssignedIds = Array.from(membershipCounts.entries())
  .filter(([, count]) => count > 1)
  .map(([id]) => id);
