  const leftBest = Math.min(...left.sources.map((source) => newsById.get(source.id_noticia)?.google_position ?? Number.POSITIVE_INFINITY));
  const rightBest = Math.min(...right.sources.map((source) => newsById.get(source.id_noticia)?.google_position ?? Number.POSITIVE_INFINITY));
  if (leftBest !== rightBest) return leftBest - rightBest;

  const leftNewest = Math.max(...left.sources.map((source) => safeTimestamp(newsById.get(source.id_noticia)?.fecha_publicacion)));
  const rightNewest = Math.max(...right.sources.map((source) => safeTimestamp(newsById.get(source.id_noticia)?.fecha_publicacion)));
  if (leftNewest !== rightNewest) return rightNewest - leftNewest;

  return (right.sources.length || 0) - (left.sources.length || 0);
});

